static std::string StableAssetKey(const avatars::AssetId& id) {
  static constexpr char hex[] = "0123456789abcdef";
  const auto* bytes = reinterpret_cast<const uint8_t*>(&id);
  std::string key(sizeof(id) * 2, '0');
  for (size_t i = 0; i < sizeof(id); ++i) {
    key[i * 2] = hex[bytes[i] >> 4];
    key[i * 2 + 1] = hex[bytes[i] & 15];
  }
  return key;

