void ApplySort(AvatarSortMode mode) {
  if (item_count_ < 2) return;
  std::vector<av2::closet_filter::Item> metadata;
  metadata.reserve(item_count_);
  for (size_t i = 0; i < item_count_; ++i) {
    X_AVATAR_ASSET_INFO info{};
    std::memcpy(&info, buffer_.data() + i * item_size(), item_size());
    std::string name, game;
    for (const auto& ch : info.name) { const uint16_t v = ch; if (!v) break; name.push_back(v < 128 ? char(v) : '?'); }
    for (const auto& ch : info.title_name) { const uint16_t v = ch; if (!v) break; game.push_back(v < 128 ? char(v) : '?'); }
    metadata.push_back(FilterItem(std::move(name), uint32_t(info.categories), std::move(game),
                                  &info.asset_id));
  }
  av2::closet_filter::SortMode selected = av2::closet_filter::SortMode::kName;
  switch (mode) {
    case AvatarSortMode::kType: selected = av2::closet_filter::SortMode::kType; break;
    case AvatarSortMode::kSourceGame: selected = av2::closet_filter::SortMode::kSourceGame; break;
    case AvatarSortMode::kCategory: selected = av2::closet_filter::SortMode::kCategory; break;
    case AvatarSortMode::kColor: selected = av2::closet_filter::SortMode::kColor; break;
    case AvatarSortMode::kRecentlyUsed: selected = av2::closet_filter::SortMode::kRecentlyUsed; break;
    default: break;
  }
  const auto order = av2::closet_filter::select(metadata, {}, selected);
  std::vector<uint8_t> sorted(buffer_.size());
  for (size_t i = 0; i < order.size(); ++i)
    std::memcpy(sorted.data() + i * item_size(), buffer_.data() + order[i] * item_size(), item_size());
  buffer_.swap(sorted);

