static bool CatalogFilterMatches(std::string name, uint32_t categories,
                                 std::string source_game = {},
                                 const avatars::AssetId* asset_id = nullptr) {
  AvatarCatalogFilter state;
  {
    std::lock_guard<std::mutex> lock(g_catalog_filter_mutex);
    state = g_catalog_filter;
  }
  av2::closet_filter::Filter filter;
  filter.type = state.type;
  filter.source_game = state.source_game;
  filter.category = state.category;
  filter.color = state.color;
  filter.tag = state.tag;
  filter.favorites_only = state.favorites_only;
  return av2::closet_filter::matches(FilterItem(std::move(name), categories,
                                                std::move(source_game), asset_id), filter);
}

