std::vector<AvatarFilterChoice> QueryAvatarFilterChoices(AvatarFilterDimension dimension) {
  std::vector<av2::closet_filter::Item> owned;
  avatars::AssetPack* pack =
      (g_title_version < 3) ? &g_legacy_avatar_asset_pack : &g_avatar_asset_pack;
  if (!pack->is_loaded() && !LoadAvatarAssetPack()) pack = nullptr;
  if (pack && pack->is_loaded()) {
    const auto& infos = pack->asset_infos();
    std::vector<bool> companion(infos.size(), false);
    for (size_t i = 0; i < infos.size(); ++i) {
      const auto& id = infos[i].asset_ids[0];
      if (!id.is_zero() && id.b != i && id.b < infos.size()) companion[id.b] = true;
    }
    for (size_t i = 0; i < infos.size(); ++i) {
      if (!(infos[i].flags & 1) || companion[i]) continue;
      const auto name16 = pack->GetAssetNameByIndex(i);
      std::string name; name.reserve(name16.size());
      for (char16_t ch : name16) name.push_back(ch < 128 ? char(ch) : '?');
      avatars::AssetId id = infos[i].asset_ids[0];
      if (id.is_zero() || id.b.get() != static_cast<uint16_t>(i)) {
        id.a = infos[i].categories;
        id.b = static_cast<uint16_t>(i);
        id.c = infos[i].bodies ? infos[i].bodies : 3;
        std::memcpy(id.d, kPackAssetGuidTail, sizeof(id.d));
      }
      owned.push_back(FilterItem(std::move(name), infos[i].categories, {}, &id));
    }
  }
  for (const auto& item : avatars::GetCloset().items())
    owned.push_back(FilterItem(item.name, item.categories, item.title_name, &item.id));
  av2::closet_filter::Dimension selected = av2::closet_filter::Dimension::kType;
  switch (dimension) {
    case AvatarFilterDimension::kType: selected = av2::closet_filter::Dimension::kType; break;
    case AvatarFilterDimension::kSourceGame: selected = av2::closet_filter::Dimension::kSourceGame; break;
    case AvatarFilterDimension::kCategory: selected = av2::closet_filter::Dimension::kCategory; break;
    case AvatarFilterDimension::kColor: selected = av2::closet_filter::Dimension::kColor; break;
    case AvatarFilterDimension::kTag: selected = av2::closet_filter::Dimension::kTag; break;
  }
  std::vector<AvatarFilterChoice> result;
  for (auto& value : av2::closet_filter::choices(owned, selected))
    result.push_back({std::move(value.label), uint32_t(value.count)});
  return result;

